import { describe, it, expect } from 'vitest'
import { readFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { scanPptx } from '../src/core/scan'

/**
 * These run everywhere — the fixture is generated by
 * scripts/make-test-deck.mjs and committed, unlike the real decks.
 *
 * It is built to contain exactly the shapes that break naive scanners, so
 * this file is the regression net for the two things the project exists to
 * get right.
 */
const deck = () =>
  new Uint8Array(readFileSync(fileURLToPath(new URL('./fixtures/synthetic.pptx', import.meta.url))))

describe('synthetic deck', () => {
  it('reports 5 real fonts, not the 33 a naive scan would find', () => {
    const r = scanPptx(deck())
    expect(r.fonts.map((f) => f.name).sort()).toEqual([
      'Bebas Neue',
      'Courier New',
      'Lato',
      'Lobster',
      'Lobster Two Bold',
    ])
    expect(r.ignoredFallbacks.length).toBeGreaterThanOrEqual(27)
  })

  it('never reports a script-fallback font as used', () => {
    const r = scanPptx(deck())
    const names = new Set(r.fonts.map((f) => f.name))
    for (const noise of ['Mangal', 'DokChampa', 'Mongolian Baiti', 'MV Boli', 'Yu Gothic']) {
      expect(names.has(noise)).toBe(false)
      expect(r.ignoredFallbacks).toContain(noise)
    }
  })

  it('resolves +mn-lt through the theme onto the slide tier', () => {
    const r = scanPptx(deck())
    const lato = r.fonts.find((f) => f.name === 'Lato')!
    expect(lato.tier).toBe('slide')
    expect(lato.origins.some((o) => o.viaThemeRef === '+mn-lt')).toBe(true)
  })

  it('strips a style suffix into family plus weight', () => {
    const r = scanPptx(deck())
    const lt = r.fonts.find((f) => f.name === 'Lobster Two Bold')!
    expect(lt.family).toBe('Lobster Two')
    expect(lt.weight).toBe(700)
  })

  it('separates a used layout from an unused one', () => {
    const r = scanPptx(deck())
    // slideLayout1 is referenced by slide1; slideLayout2 is not.
    expect(r.fonts.find((f) => f.name === 'Lato')!.tier).toBe('slide')
    expect(r.fonts.find((f) => f.name === 'Bebas Neue')!.tier).toBe('inherited')
    expect(r.fonts.find((f) => f.name === 'Courier New')!.tier).toBe('elsewhere')
  })

  it('finds no embedded fonts in a deck that has none', () => {
    const r = scanPptx(deck())
    expect(r.embedded).toHaveLength(0)
    expect(r.fonts.every((f) => !f.embedded)).toBe(true)
  })
})
